// th16_s6_b2 — TH16 v1.00a Stage 6 boss spell 70-73 「後符「秘神の後光」」.
// Source: st06bs.ecl.txt BossCard1 757-821 (entry) + BossCard1_at 823-877 (danmaku).
//
// Source -> target frame relation: source times below are relative to the boss
// task's first instruction; the shell spawns the boss OPENING_BUFFER frames
// after the stage task starts, so card frame = 120 + source time (+ startup).
//
// Omitted per transcription policy (recorded in report.md):
//   BossItemCard drops, entry etCancel/etClear + killAllAsync/enmKillAll/spellEnd
//   hand-off, the zeroing moveVel/movePosTime(0,0,0,0), funcSet(0)/laserCancel,
//   sounds and ANIM/BRIGHT presentation, and the bullet's non-judging line-laser
//   afterglow child (EX LASER L=16 is under the source's L>16 judgment gate).

const TIME_LIMIT: int = 2824;   // 120 buffer + 2700 source window + 4 startup
const OPENING_BUFFER: int = 120;

const TH16_BALL2: int = 432;    // source etSprite type 5, colors 0-15

// ---------------------------------------------------------------------------
// Boss main task: BossCard1 0794-0819.
// Boss entry already holds (0,128); movePosTime(60,4,0,128) is a zero move.
// moveLimit(0,128,240,224) => clamp x[-120,120], y[16,240].
// ---------------------------------------------------------------------------
async sub boss_main() {
    set_invuln(65535);
    // Boss 0029-0030: setHurtbox(56,56) / setHitbox(50,50); circle radius = first/2.
    set_hurtbox(28fx);
    set_hitbox(25fx);

    wait(90);                 // 0799 +90:
    wait(60);                 // 0801
    spawn boss_card1_at();    // 0804 @BossCard1_at() async
    // 0806 goto _1348 @90 -> 0810 wait(300) -> 0811 moveRand -> 0812 wait(60)
    loop {
        wait(300);
        move_rand();
        move_rand_steps(60);  // the source wait(60) at 0812; 60 movement ticks
    }
}

// ---------------------------------------------------------------------------
// BossCard1_at 0826-0875: one emitter configured once, then a fixed fan whose
// base angle turns clockwise by 7deg + RANDF2*1deg per volley.
// etAim(0,1) fixed fan, etSprite(0,5,6/2), etCount(0,1/2/2/3,1), etSpeed 1.5,
// etDist 48 combined with ANIM birth displacement -4*1.5 => net 42px.
// ---------------------------------------------------------------------------
async sub boss_card1_at() {
    var color: int = 6;       // 0838-0845: !E 6 !N 6 !H 6 !LO 2
    var ways: int = 1;        // 0838-0847: !E 1 !N 2 !H 2 !LO 3
    var period: int = 6;      // 0864-0873: !E 6 !N 6 !H 5 !LO 6
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { ways = 2; }
    if rank == RANK_HARD { ways = 2; period = 5; }
    if rank == RANK_LUNATIC { ways = 3; color = 2; }

    sh_reset(0);
    sh_sprite(0, TH16_BALL2, color);
    sh_ring(0, 0);
    sh_aim(0, 0);
    sh_count(0, ways, 1);
    sh_speed(0, 1.5fx, 0fx);
    sh_dist(0, 42fx);
    // EX 0850-0856: ANIM(1) birth and BRIGHT are presentation; BOUNCE(1,15) is
    // followed by LASER (0853-0854) which deletes the parent at its first wall
    // contact. The target keeps no bounce_arm (engine bounce reflects and would
    // re-enter the field); off-field cleanup stands in for that same end point.

    var a: int = 0;           // 0857 %A = 0
    var t: int = 0;           // source timeout stops BossCard1_at at entry+2700;
    while t < 2550 {          // it starts at entry+150, so 2550 firing frames
        sh_angle(0, a as angle, 30deg);   // 0861 etAngle(0, %A, 0.5235988)
        sh_fire(0);                       // 0862 etOn(0)
        // 0863 %A -= 0.12217305 + RANDF2 * 0.017453292  (RANDF2 in [-1,1])
        var u: int = rand(65536) - 32768;
        a = a - (1274 + u * 182 / 32768);
        wait(period);                     // 0864-0873
        t = t + period;
    }
}

// ---------------------------------------------------------------------------
// 0811 moveRand(60,4,1.9) — movement.md recipe with this card's moveLimit:
// direction inner region x +-60, y 72..184; outer clamp x +-120, y 16..240.
// int slot 0 = next step count, fx slots 0/1 = logical unit direction.
// ---------------------------------------------------------------------------
sub move_rand() {
    // 405b90 = signed unit random * pi; values stay unwrapped BAM ints.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }   // source normalizes only this branch
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 72fx {
        if a < 0 { a = -a; }
    } else if $self_y > 184fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // native +-pi/2 guard, epsilon 0.05 rad in BAM
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_rand_step();
}

sub move_rand_steps(frames: int) {
    for i in 0..frames {
        wait(1);
        move_rand_step();
    }
}

sub move_rand_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * (60 - k) / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 16fx { ny = 16fx; }
    if ny > 240fx { ny = 240fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// ---------------------------------------------------------------------------
// Independent invulnerable shell (validation.md): control owns the phase,
// real enemy is spawned after the opening buffer.
// ---------------------------------------------------------------------------
async sub opening_pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, opening_pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
